mapper.select:
select uavNest.deviceCode from (
select t.device_code deviceCode,
(case when length(IFNULL(rel.device_name, '')) = 0 then t.device_name else rel.device_name end ) deviceName
from `vm_uav_nest_device_info` t
LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = t.device_code
and rel.tenant_id = #{param.tenantId} and rel.industry_code = #{param.industryCode}
and rel.delete_flag = '0' and rel.device_type = 4
where t.delete_flag = 0

    AND t.manufacturer_code = #{param.uavNestManufacturerCode}


    AND t.model_code = #{param.uavNestModelCode}


    AND t.resource_status = #{param.uavNestStatus}



    AND t.resource_status = #{param.uavNestStatus}



    and t.resource_status in

        #{item}



) uavNest


        and uavNest.deviceName like CONCAT('%', #{param.uavNestName}, '%')

SELECT COUNT( IF ( a.status = '0', 1, NULL )) AS uavDeviceOnlineCount, COUNT( IF ( a.status = '1', 1, NULL )) AS uavDeviceOfflineCount, COUNT( `deviceCode` ) AS uavDeviceCount FROM (SELECT DISTINCT uav.device_code deviceCode, uav.device_status status from vm_uav_device_info_t uav
inner JOIN ( SELECT DISTINCT device_code FROM vm_order_uav_devices WHERE ord_status IN ( '0', '1', '2' ) AND delete_flag = 0 ) t2 ON uav.device_code = t2.device_code
where uav.delete_flag ='0'
and exists(select od.id from vm_order_uav_devices od join sys_tenant_info ti on od.tenant_id = ti.tenant_id where od.device_code = uav.device_code and od.delete_flag ='0' and ti.del_flag = '0' and od.tenant_id = #{tenantId})
and uav.device_type = #{deviceType}
and ( uav.province_code in
#{item}
or uav.city_code in
#{item}
or uav.county_code in
#{item}
or uav.town_code in
#{item}
)
AND uav.device_code in
#{deviceCode}
${dataScope}) a
